import{_ as e,o as t,c as r,a6 as o}from"./chunks/framework.Bd7kzaCy.js";const _=JSON.parse('{"title":"真实案例","description":"从可核对的事件与制度流程出发，理解接口、反馈和行动之间的区别。","frontmatter":{"title":"真实案例","description":"从可核对的事件与制度流程出发，理解接口、反馈和行动之间的区别。"},"headers":[],"relativePath":"cases/index.md","filePath":"cases/index.md"}'),n={name:"cases/index.md"};function s(i,a,p,d,h,l){return t(),r("div",null,[...a[0]||(a[0]=[o('<h1 id="在真实事件里理解概念" tabindex="-1">在真实事件里理解概念 <a class="header-anchor" href="#在真实事件里理解概念" aria-label="Permalink to &quot;在真实事件里理解概念&quot;">​</a></h1><p>案例首先回答发生了什么，再说明它帮助我们注意哪一项区别。事件事实、来源的解释，以及借助理论提出的阅读问题，各自保持身份。</p><h2 id="一份数据-怎样失去了共同含义" tabindex="-1">一份数据，怎样失去了共同含义？ <a class="header-anchor" href="#一份数据-怎样失去了共同含义" aria-label="Permalink to &quot;一份数据，怎样失去了共同含义？&quot;">​</a></h2><p>1999 年火星气候轨道器失联。NASA 调查报告指出了地面软件与导航软件之间的单位不一致，也讨论了验证和沟通环节的问题。</p><p>从这件事看<strong>接口、表示与整链</strong>：数据文件被交付，不等于同一个量已经被正确理解和使用。</p><p><a href="./mars-climate-orbiter.html">阅读火星气候轨道器案例 →</a></p><h2 id="发现问题之后-谁能让下一步改变" tabindex="-1">发现问题之后，谁能让下一步改变？ <a class="header-anchor" href="#发现问题之后-谁能让下一步改变" aria-label="Permalink to &quot;发现问题之后，谁能让下一步改变？&quot;">​</a></h2><p>丰田公开介绍的安灯与自働化流程，把异常发现、呼叫、响应和必要时停止生产连接起来。</p><p>从这个流程看<strong>反馈与执行条件</strong>：信息能够被看见之后，还要有可响应的人、权限和实际动作。</p><p><a href="./toyota-andon.html">阅读丰田安灯案例 →</a></p><h2 id="怎样使用这些案例" tabindex="-1">怎样使用这些案例 <a class="header-anchor" href="#怎样使用这些案例" aria-label="Permalink to &quot;怎样使用这些案例&quot;">​</a></h2><p>读一个案例时，保留三个问题：来源实际证明了什么？概念帮助区分了什么？还有哪些结论不能从这件事推出？一个案例能澄清某个区别，并不自动证明它适用于所有组织与所有情形。</p><p>需要先了解概念，可以进入<a href="./../concepts/">概念图解</a>；需要核对定义，可以回到<a href="./../theory/">理论原文</a>。</p>',13)])])}const m=e(n,[["render",s]]);export{_ as __pageData,m as default};
